import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Study Plan — README","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/README.md","filePath":"todo/study_plan/README.md"}'),n={name:"todo/study_plan/README.md"};function s(d,t,i,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="study-plan-—-readme" tabindex="-1">Study Plan — README <a class="header-anchor" href="#study-plan-—-readme" aria-label="Permalink to &quot;Study Plan — README&quot;">​</a></h1><p>Navigation hub for the study plan. This file is enough to orient day-to-day.</p><h2 id="what-this-is" tabindex="-1">What this is <a class="header-anchor" href="#what-this-is" aria-label="Permalink to &quot;What this is&quot;">​</a></h2><p>A 9-month executable study plan covering 32 Parts of backend / SDE mastery (per-Part docs in <code>parts/</code> are the authoritative syllabus). Three-month Sprint (12 weeks, priority-Part order, last 3 weeks shift toward mocks) then six-month Consolidation.</p><h2 id="folder-layout" tabindex="-1">Folder layout <a class="header-anchor" href="#folder-layout" aria-label="Permalink to &quot;Folder layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>study_plan/</span></span>
<span class="line"><span>├── README.md             ← you are here (read first)</span></span>
<span class="line"><span>├── MasterSchedule.md     ← weekly calendar — open every Monday</span></span>
<span class="line"><span>├── parts/                ← the 32 Part docs (your syllabus)</span></span>
<span class="line"><span>├── deep_dives/           ← long-form study material</span></span>
<span class="line"><span>└── reference/            ← look up when you need it</span></span>
<span class="line"><span>    ├── TopicIndex.md</span></span>
<span class="line"><span>    ├── PracticeProblems.md</span></span>
<span class="line"><span>    ├── Resources.md</span></span>
<span class="line"><span>    └── ConsolidationOutline.md</span></span></code></pre></div><h2 id="what-to-open-when" tabindex="-1">What to open when <a class="header-anchor" href="#what-to-open-when" aria-label="Permalink to &quot;What to open when&quot;">​</a></h2><table tabindex="0"><thead><tr><th>When you…</th><th>Open</th></tr></thead><tbody><tr><td>Start the week (Mon morning)</td><td><code>MasterSchedule.md</code></td></tr><tr><td>Study a topic</td><td><code>parts/Part_NN_&lt;title&gt;.md</code></td></tr><tr><td>Forget where a concept lives</td><td><code>reference/TopicIndex.md</code></td></tr><tr><td>Saturday practice (Week 4+ LLD, Week 6+ HLD)</td><td><code>reference/PracticeProblems.md</code></td></tr><tr><td>Deep-dive a topic that needs more than its Part rows</td><td><code>deep_dives/</code></td></tr><tr><td>Need a book / video / tool</td><td><code>reference/Resources.md</code></td></tr><tr><td>Finish the Sprint</td><td><code>reference/ConsolidationOutline.md</code></td></tr></tbody></table><h2 id="how-to-read-a-part-planning-doc" tabindex="-1">How to read a Part planning doc <a class="header-anchor" href="#how-to-read-a-part-planning-doc" aria-label="Permalink to &quot;How to read a Part planning doc&quot;">​</a></h2><p>Each doc has:</p><ol><li><strong>Topic table</strong> — one row per syllabus bullet, priority-sorted (🔴 first, then 🟠, 🟡). Columns: # · Topic · Tags · Tier · Time · Done · Partial · Grilling · Visit Again · Notes · Resources. Resources is sparse (~20-30% of rows); icons: 📺 video · 🎓 tutorial · 📖 read · 💻 practice.</li><li><strong>Time summary</strong> — 3-row table: 🔴 only / 🔴+🟠 / Full Part. Hours, weeks @ 10-12 hrs/wk, and an empty &quot;Actual time&quot; cell.</li><li><strong>Frequently asked</strong> — 3-10 senior-level interview questions.</li><li><strong>Trick questions / gotchas</strong> — 2-5 non-obvious traps.</li><li><strong>Mastery candidates</strong> — top 3-5 from this Part (suggestions, not commitments).</li><li><strong>Quick recall</strong> — 4-6 Q&amp;As for self-test.</li></ol><p><strong>Checkbox semantics:</strong> tick <strong>Done</strong> when you can give a 2-min out-loud explanation. Tick <strong>Partial</strong> when a row is only partially covered (the <code>Notes</code> cell says what&#39;s covered vs pending) — these are cheap wins to wrap up later; untick Partial when the row graduates to Done. Tick <strong>Grilling</strong> when Claude has drilled hard questions on the topic and you&#39;ve held up. Tick <strong>Visit Again</strong> when shaky or caught by a trick question. Edit by typing <code>x</code> between the brackets: <code>[ ]</code> → <code>[x]</code>. To find all partials: search <code>| [x] |</code> in the Partial column or grep <code>Partial:</code> in Notes.</p><h2 id="tier-symbols" tabindex="-1">Tier symbols <a class="header-anchor" href="#tier-symbols" aria-label="Permalink to &quot;Tier symbols&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>Time</th><th>What it means</th></tr></thead><tbody><tr><td><strong>L</strong></td><td>15-30 min</td><td>Definitions, term recognition</td></tr><tr><td><strong>M</strong></td><td>30-60 min</td><td>One diagram or example</td></tr><tr><td><strong>MP</strong></td><td>1-2 hrs</td><td>Examples + write a one-pager</td></tr><tr><td><strong>D</strong></td><td>2-4 hrs</td><td>Mental model + trick-question handling</td></tr><tr><td><strong>VD</strong></td><td>4-8 hrs</td><td>Hands-on demo or multi-page deep doc</td></tr></tbody></table><h2 id="tag-legend" tabindex="-1">Tag legend <a class="header-anchor" href="#tag-legend" aria-label="Permalink to &quot;Tag legend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priority</th><th>Context</th></tr></thead><tbody><tr><td>🔴 MUST</td><td>💼 daily backend work</td></tr><tr><td>🟠 HIGH</td><td>🎯 system design / LLD interview</td></tr><tr><td>🟡 MED</td><td>🔐 KYC / identity domain</td></tr><tr><td>🟢 LOW</td><td>🆕 modern / emerging</td></tr><tr><td>⚪ OPTIONAL</td><td></td></tr></tbody></table><h2 id="current-phase-week" tabindex="-1">Current phase + week <a class="header-anchor" href="#current-phase-week" aria-label="Permalink to &quot;Current phase + week&quot;">​</a></h2><blockquote><p><strong>Sprint start:</strong> Monday, May 18, 2026 (Week 1 = May 18–24) <strong>Phase:</strong> Sprint <strong>Week:</strong> 3 (Jun 1–7) — <em>(update each Monday)</em><strong>Today&#39;s deliverable:</strong> <em>(update each session)</em></p></blockquote><h2 id="if-you-re-behind-schedule" tabindex="-1">If you&#39;re behind schedule <a class="header-anchor" href="#if-you-re-behind-schedule" aria-label="Permalink to &quot;If you&#39;re behind schedule&quot;">​</a></h2><ul><li>Defer any unstarted Mastery items to Consolidation.</li><li>Compress Conversant items to read + 5-min verbal self-explain (skip the deep write-up).</li></ul><h2 id="if-you-re-ahead" tabindex="-1">If you&#39;re ahead <a class="header-anchor" href="#if-you-re-ahead" aria-label="Permalink to &quot;If you&#39;re ahead&quot;">​</a></h2><ul><li>Promote one 🟠 HIGH item from Consolidation into the current Sprint week.</li><li>Pull a Part 4 structural pattern forward, OR walk one Part 31.9 cross-question out loud.</li></ul>`,22)])])}const m=e(n,[["render",s]]);export{u as __pageData,m as default};
